"""All-sign anonymous factorial group export and explicit mechanism limits."""
from pathlib import Path
import copy,json,math,sys
ROOT=Path(__file__).resolve().parents[1];sys.path.insert(0,str(ROOT))
from scripts.run_stvg_B_transfer_v1 import BASE,PRIOR,read,put,sha,recipe
from scripts.score_stvg_referent_abc_v1 import aggregate
def main(arm):
    b=BASE/'trials'/arm;d=read(b/'POSTSEAL_RESULTS.json');assert read(b/'CPU_COMPLETION.json')['result_sha256']==sha(b/'POSTSEAL_RESULTS.json');s,p=aggregate(d['rows']);assert s==d['summary']and p==d['paired'];sa,pa=aggregate(d['actual_support_rows']);assert sa==d['actual_support_summary']and pa==d['actual_support_paired'];assert read(b/'PREFIX_READBACK.json')['status']=='pass'
    aliases={cid:f'R{i:03}'for i,cid in enumerate(sorted({r['case_id']for r in d['rows']}),1)}
    def anon(x):
        if isinstance(x,list):return[anon(y)for y in x]
        if isinstance(x,dict):return{(aliases[k]if k in aliases else 'gradient_max_abs_error'if k=='gradient'else k):(aliases[v]if k=='case_id'else anon(v))for k,v in x.items()}
        return x
    out=ROOT/'results/stvg_B_transfer/2026-10-16'/arm;out.mkdir(parents=True,exist_ok=False);put(out/'RESULTS.json',dict(status='complete',count=16,rows=anon(d['rows']),summary=s,paired=anon(p),all_positive_negative_neutral_unknown_preserved=True,GT_read=True));put(out/'ACTUAL_GRADIENT_SUPPORT.json',dict(status='complete',rows=anon(d['actual_support_rows']),summary=sa,paired=anon(pa),GT_read=True,note='same original B adopted physical anchors for every arm, separately from four prospective observation times'))
    put(out/'GEOMETRY_AND_ACCEPTANCE.json',dict(status='complete',count=16,geometry=anon(d['geometry']),usage=anon(d['usage']),baseline_acceptance=anon(read(BASE/'BASELINE_ACCEPTANCE_READBACK.json')['records']),prefix_readback=anon(read(b/'PREFIX_READBACK.json')['records']),GT_read=True,limits=d['geometry_limit']))
    designs=read(b/'DESIGN_LOCK.json');cost={m:read(BASE/'execution'/arm/m/'WORKER_EXIT.json')['wall_seconds']for m in ('worker','root')};put(out/'CONFIG_AND_COST.json',dict(status='complete',count=16,design=read(BASE/'DESIGN_LOCK.json'),actual_recipe=recipe(arm),configs=designs['configs'],response_settings=designs['response_settings'],new_external_Teacher_calls=0,new_backbones=0,new_Temporal_calls=0,actual_fits=sum(r['actual_fit']for r in d['usage']if r['arm']==arm),nonzero_final=sum(r['nonzero_final']for r in d['usage']if r['arm']==arm),worker_wall_seconds=cost,score_wall_seconds=read(b/'CPU_COMPLETION.json')['wall_seconds'],inherited_source_Teacher_cost='prior B native evidence; not a zero-cost raw deployment pipeline',unchanged_rejection=True,GT_read=False))
    put(out/'ROOT_PUBLIC_READBACK.json',dict(status='pass',count=16,row_count=len(d['rows']),all_common_and_actual_support_scalar_aggregates_and_pairs_recomputed=True,all_source_signs_and_nulls_preserved=True,result_sha256=sha(b/'POSTSEAL_RESULTS.json'),Student_root_sha256=sha(b/'ROOT_READBACK.json'),prefix_root_sha256=sha(b/'PREFIX_READBACK.json'),GT_read=True))
    (out/'PROTOCOL.md').write_text((ROOT/'protocols/stvg_B_transfer_v1.md').read_text())
    from scripts.export_stvg_lite_batch001 import public_source_text
    names=('run_stvg_B_transfer_v1.py','audit_stvg_B_transfer_v1.py','score_stvg_B_transfer_v1.py','report_stvg_B_transfer_v1.py','publish_stvg_B_transfer_v1.py','stvg_spatial_lite_fit_v1.py','stvg_weightfree_coordinate_fit002.py','audit_stvg_spatial_lite_fit002.py');bindings=[]
    for n in names:
        f=ROOT/'scripts'/n;q=out/'code'/n;q.parent.mkdir(exist_ok=True);q.write_text(public_source_text(f.read_bytes()));bindings.append(dict(name=n,source_sha256=sha(f),public_sha256=sha(q)))
    put(out/'SOURCE_BINDINGS.json',dict(status='pass',records=bindings,study_runtime_sha256=sha(BASE/'RUNTIME.json'),trial_runtime_sha256=sha(b/'RUNTIME.json'),scorer_lock_sha256=sha(BASE/'SCORER_LOCK.json')))
    import matplotlib;matplotlib.use('Agg');import matplotlib.pyplot as plt
    fig,axes=plt.subplots(1,2,figsize=(11,4))
    for ax,ds in zip(axes,('hc2','vidstg')):
        for i,base in enumerate(('B00','Temporal','Frozen')):
            r=next(x for x in p if x['dataset']==ds and x['comparison']==arm+'_minus_'+base and x['metric']=='m_vIoU');v=list(r['per_source_delta_pp'].values());ax.scatter([i]*len(v),v,s=22,alpha=.7);ax.scatter([i],[r['mean_delta_pp']],marker='_',s=500,c='black',zorder=4)
        ax.axhline(0,color='gray',lw=.8);ax.set_xticks(range(3),['vs original B','vs Temporal','vs Frozen']);ax.set_ylabel('Actual Student vIoU delta (pp)');ax.set_title(ds+' / 8 exposed sources')
    fig.suptitle(arm+': extent and guarded step reachability; all sources retained');fig.tight_layout();fig.savefig(out/'paired_effects.png',dpi=150);plt.close(fig)
    lines=['# B evidence transfer: '+arm,'','This group belongs to one prelocked reference-extent x guarded-step factorial on sixteen exposed development sources, eight independent parents per domain. B00 reuses the exact original B; G10 changes reference extent only, R01 changes guarded step reachability only, GR11 combines them. Both domains run regardless of gain. No GT-dependent candidate/ID, extent, step or parameter choice is allowed.','',
      '| Student arm | HC vIoU % | VidSTG vIoU % |','|---|---:|---:|']
    for a in ('Frozen','Temporal','B00','B00_Spatial',arm+'_Spatial',arm):lines.append('| '+a+' | '+' | '.join(f"{100*next(x['mean']for x in s if x['dataset']==ds and x['arm']==a and x['metric']=='m_vIoU'):.6f}"for ds in ('hc2','vidstg'))+' |')
    lines+=['','| Domain | Contrast | Delta pp | Positive / negative / unchanged |','|---|---|---:|---|']
    for r in p:
        if r['comparison']in (arm+'_minus_B00',arm+'_minus_Temporal')and r['metric']=='m_vIoU':lines.append(f"| {r['dataset']} | {r['comparison']} | {r['mean_delta_pp']:+.6f} | {r['positive']} / {r['negative']} / {r['neutral']} |")
    lines+=['','The1.25 extent intervention keeps the original B chosen identity, exact centers, anchor times, admission and weights. Width/height are limited symmetrically by image borders. This is a coverage perturbation, not certified complete-object geometry or independent new visual evidence. It may add background or another participant. Known-anchor IoU/target-area coverage/reference precision are supplied; missing annotations stay unknown and all anchors remain included in training.','',
      'Both step recipes retain exactly the same finite-box and equal-anchor mean reference-IoU nondecrease condition with1e-7 tolerance, the same Adam rollback and early stop after every allowed scale fails. R01/GR11 use original lite_backtrack[1,.5,.25,.125], with the original full proposal tried first. No rejected proposal is forced through. The original Gaussian reward, likelihood loss, response direction, lr/sigma/tau/steps and Source/Temporal clocks stay fixed.','',
      'Original B has16 actual fits,13 nonzero final states and only3 rejected-query cases: one HC, two Vid. The other13 cases already accept updates. Rejection cannot explain every missing gain. Saved common-prefix full-proposal comparisons in R01 distinguish an oversized rejected step rescued at a smaller scale from persistent failure; later trajectories can diverge after a rescue. More acceptance alone is not a task benefit.','',
      '| Domain | Known anchor positions | Unknown positions | Mean coverage change | Mean precision change | Mean reference IoU change |','|---|---:|---:|---:|---:|']
    for ds in ('hc2','vidstg'):
        rr=[r for r in d['geometry']if r['dataset']==ds];known=[r for r in rr if r['known_GT']];vals=[100*math.fsum(r['intervention'][k]-r['B00'][k]for r in known)/len(known)if known else None for k in ('target_coverage','reference_precision','IoU')];lines.append(f'| {ds} | {len(known)} | {len(rr)-len(known)} | '+' | '.join(f'{v:+.6f} pp'if v is not None else'unknown'for v in vals)+' |')
    lines+=['','Anchor means describe exact observed positions and are not full-Tube source-macro effects. Both prospective observation support and actual adopted-gradient support sIoU are exported, with all nulls. Five full Student metrics use the same original official and independent paths only after all16 complete predictions and saved-math/readout roots pass. The audit is not a second complete backward. Identity labels from the old sparse panel are not relabelled as complete-object truth after expansion.','',
      'All positive, negative, unchanged, no-reference/flat/no-update and rejected cases are retained. No Bootstrap/CURRENT promotion/fullset/new monitor or additional model was introduced. Source/Teacher/caption generation is inherited, not zero deployment cost. Private media, actual Query/caption text, raw Teacher responses, GT coordinates, vectors, parameters and optimizer payloads are excluded. Each completed group is uploaded separately; this individual receipt does not imply the entire factorial is complete.']
    doc=ROOT/'docs'/('STVG_B_TRANSFER_'+arm+'_001.md');doc.write_text('\n'.join(lines)+'\n');paths={str(f.relative_to(ROOT))for f in out.rglob('*')if f.is_file()}|{str(doc.relative_to(ROOT))};put(BASE/'publication'/arm/'EXPORT_MANIFEST.json',dict(status='complete',paths=sorted(paths),files=[dict(path=f,sha256=sha(ROOT/f),bytes=(ROOT/f).stat().st_size)for f in sorted(paths)]));print(json.dumps(dict(status='exported_pending_view_privacy_remote',arm=arm,files=len(paths))))
if __name__=='__main__':main(sys.argv[1])
